<script setup>
import {ref,watch} from 'vue';import api from '../../services/api';
const props=defineProps({clientId:{type:Number,required:true}}),emit=defineEmits(['updated']);
const data=ref(null),error=ref(''),saving=ref(false),selected=ref({}),reasons=ref({});let generation=0;
async function load(){const run=++generation;data.value=null;error.value='';selected.value={};reasons.value={};try{const r=await api.get(`/clients/${props.clientId}/demographic-updates`,{skipGlobalLoading:true});if(run===generation)data.value=r.data;}catch(e){if(run===generation&&e.response?.status!==403)error.value=e.response?.data?.error?.message||'Could not load demographic updates.';}}
async function review(row){const id=props.clientId,run=generation;if(saving.value)return;saving.value=true;error.value='';try{await api.post(`/clients/${id}/demographic-updates/${row.id}/review`,{acceptedFields:selected.value[row.id]||[],reason:reasons.value[row.id],revision:data.value.revision},{skipGlobalLoading:true});if(run===generation){await load();emit('updated');}}catch(e){if(run===generation)error.value=e.response?.data?.error?.message||'Could not review these changes.';}finally{saving.value=false;}}
watch(()=>props.clientId,load,{immediate:true});
</script>
<template><section v-if="data?.requests.length||error" class="demographic-review"><h3>Parent updates to client details</h3><p>Compare each submitted value with the current record. Select only the changes to apply; the other values stay as recorded. A birth-date correction also requires the care team to review clinical access again.</p><article v-for="r in data?.requests||[]" :key="r.id"><h4>{{r.submittedBy}} · {{new Date(r.createdAt).toLocaleString()}} · {{r.status}}</h4><div class="review-table"><table><thead><tr><th>Detail</th><th>At submission</th><th>Current record</th><th>Submitted update</th><th v-if="r.status==='pending'">Apply</th></tr></thead><tbody><tr v-for="(value,key) in r.proposed" :key="key"><th>{{data.fields[key]}}</th><td>{{r.base[key]||'—'}}</td><td>{{data.values[key]||'—'}} <small v-if="r.base[key]!==data.values[key]">Changed since submission</small></td><td>{{value||'—'}}</td><td v-if="r.status==='pending'"><input type="checkbox" :aria-label="`Apply ${data.fields[key]}`" :value="key" :checked="selected[r.id]?.includes(key)" @change="selected[r.id]=$event.target.checked?[...(selected[r.id]||[]),key]:(selected[r.id]||[]).filter(k=>k!==key)" /></td></tr></tbody></table></div><form v-if="r.status==='pending'" @submit.prevent="review(r)"><label>Review reason<input v-model="reasons[r.id]" required maxlength="2000" /></label><button :disabled="saving">Save review decision</button></form><p v-else>{{r.review?.reason}}</p></article><p v-if="error" role="alert">{{error}} <button @click="load">Reload</button></p></section></template>
<style scoped>.demographic-review{padding:16px;border:1px solid #d1ddd7;border-radius:10px;margin:16px 0}article{border-top:1px solid #ddd;padding:12px 0}.review-table{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left}td,th{padding:8px;border-bottom:1px solid #eee;vertical-align:top}small{display:block;color:#9a5300}label{display:grid;gap:6px;margin:12px 0}input:not([type=checkbox]){width:100%;box-sizing:border-box;padding:8px;font:inherit}button{padding:8px 12px;font:inherit}p[role=alert]{color:#a12727}</style>
